import anthropic
import base64
from pathlib import Path

client = anthropic.Anthropic()

def load_pdf_as_base64(path: str) -> str:
    return base64.standard_b64encode(Path(path).read_bytes()).decode("utf-8")

def extract_clause(pdf_path: str, vendor_name: str, clause_topic: str) -> str:
    pdf_data = load_pdf_as_base64(pdf_path)
    response = client.messages.create(
        model="claude-opus-4-5",
        max_tokens=1024,
        system=(
            f"You are reviewing a supplier contract for vendor: {vendor_name}. "
            f"Answer only from this document. If the clause is absent, say so explicitly."
        ),
        messages=[
            {
                "role": "user",
                "content": [
                    {"type": "document",
                     "source": {"type": "base64", "media_type": "application/pdf",
                                "data": pdf_data}},
                    {"type": "text",
                     "text": f"Extract and quote the section covering: {clause_topic}"}
                ]
            }
        ]
    )
    return response.content[0].text

result = extract_clause("acme_contract.pdf", "Acme GmbH", "liability cap")
print(result)

