import anthropic
import sqlite3

client = anthropic.Anthropic()
db = sqlite3.connect("invoices.db")

tools = [{
    "name": "query_invoices",
    "description": "Run a read-only SQL query against the invoices table.",
    "input_schema": {
        "type": "object",
        "properties": {
            "sql": {"type": "string", "description": "SELECT statement only"}
        },
        "required": ["sql"]
    }
}]

def handle_tool(name, inputs):
    if name == "query_invoices":
        sql = inputs["sql"]
        if not sql.strip().upper().startswith("SELECT"):
            return {"error": "Only SELECT statements allowed"}
        rows = db.execute(sql).fetchall()
        return {"rows": rows}

messages = [{"role": "user", "content": "Which vendors have invoices over CHF 3000 due this month?"}]

for _ in range(5):  # bounded loop
    resp = client.messages.create(model="claude-opus-4-5", max_tokens=1024, tools=tools, messages=messages)
    if resp.stop_reason == "end_turn":
        print(resp.content[0].text)
        break
    tool_use = next(b for b in resp.content if b.type == "tool_use")
    result = handle_tool(tool_use.name, tool_use.input)
    messages += [
        {"role": "assistant", "content": resp.content},
        {"role": "user", "content": [{"type": "tool_result", "tool_use_id": tool_use.id, "content": str(result)}]}
    ]

